<?php
declare(strict_types=1);$active_module='hotel_ops';require_once __DIR__.'/layout.php';if(empty($_SESSION['supplier_csrf']))$_SESSION['supplier_csrf']=bin2hex(random_bytes(32));$u=$supplier_user;$pdo=db();$message='';$error='';
try{if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['supplier_csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Güvenlik doğrulaması geçersiz.');$action=$_POST['action']??'';
if($action==='room'){$property=(int)$_POST['property_id'];$roomType=(int)$_POST['room_type_id'];$number=trim((string)$_POST['room_number']);if(!$property||!$number)throw new RuntimeException('Otel ve oda numarası zorunludur.');$pdo->prepare('INSERT INTO physical_rooms(property_id,room_type_id,room_number,floor_label,status) VALUES(?,?,?,?,\'clean\')')->execute([$property,$roomType?:null,$number,trim((string)$_POST['floor_label'])?:null]);$message='Fiziksel oda eklendi.';}
if($action==='booking'){$property=(int)$_POST['property_id'];$room=(int)$_POST['physical_room_id'];$from=$_POST['check_in'];$to=$_POST['check_out'];$first=trim((string)$_POST['first_name']);$last=trim((string)$_POST['last_name']);if(!$property||!$room||!$from||!$to||$from>=$to||$first===''||$last==='')throw new RuntimeException('Rezervasyon alanlarını kontrol edin.');$conflict=$pdo->prepare("SELECT 1 FROM booking_rooms br JOIN supplier_bookings b ON b.id=br.booking_id WHERE br.physical_room_id=? AND b.booking_status NOT IN ('cancelled','no_show','checked_out') AND b.check_in<? AND b.check_out>? LIMIT 1");$conflict->execute([$room,$to,$from]);if($conflict->fetch())throw new RuntimeException('Seçilen fiziksel oda bu tarihlerde dolu.');$pdo->beginTransaction();$email=trim((string)$_POST['email'])?:null;$guest=$pdo->prepare('INSERT INTO guest_profiles(supplier_id,first_name,last_name,email,phone,nationality) VALUES(?,?,?,?,?,?) RETURNING id');$guest->execute([$u['supplier_id'],$first,$last,$email,trim((string)$_POST['phone'])?:null,strtoupper(trim((string)$_POST['nationality'])?:'TR')]);$guestId=(int)$guest->fetchColumn();$ref='NXH-'.date('ymdHis').'-'.random_int(100,999);$booking=$pdo->prepare("INSERT INTO supplier_bookings(supplier_id,property_id,booking_reference,status,booking_status,check_in,check_out,total_amount,currency,source_code,notes) VALUES(?,?,?,'reserved','reserved',?,?,?,?,?,'manual',?) RETURNING id");$booking->execute([$u['supplier_id'],$property,$ref,$from,$to,(float)$_POST['total_amount'],$_POST['currency']??'EUR',trim((string)$_POST['notes'])?:null]);$bookingId=(int)$booking->fetchColumn();$pdo->prepare('INSERT INTO booking_guests(booking_id,guest_id,is_primary) VALUES(?,?,true)')->execute([$bookingId,$guestId]);$pdo->prepare('INSERT INTO booking_rooms(booking_id,physical_room_id,adults,children,nightly_rate,currency) VALUES(?,?,?,?,?,?)')->execute([$bookingId,$room,max(1,(int)$_POST['adults']),max(0,(int)$_POST['children']),(float)$_POST['nightly_rate'],$_POST['currency']??'EUR']);$folio=$pdo->prepare('INSERT INTO booking_folios(booking_id,currency) VALUES(?,?) RETURNING id');$folio->execute([$bookingId,$_POST['currency']??'EUR']);$pdo->commit();$message='Rezervasyon ve misafir kartı oluşturuldu: '.$ref;}
if($action==='status'){$id=(int)$_POST['booking_id'];$status=$_POST['status']??'';if(!in_array($status,['reserved','in_house','checked_out','cancelled','no_show'],true))throw new RuntimeException('Geçersiz rezervasyon durumu.');$pdo->beginTransaction();$q=$pdo->prepare('SELECT b.*,br.physical_room_id FROM supplier_bookings b LEFT JOIN booking_rooms br ON br.booking_id=b.id WHERE b.id=? AND b.supplier_id=? LIMIT 1 FOR UPDATE');$q->execute([$id,$u['supplier_id']]);$booking=$q->fetch();if(!$booking)throw new RuntimeException('Rezervasyon bulunamadı.');$pdo->prepare('UPDATE supplier_bookings SET booking_status=?,status=?,checked_in_at=CASE WHEN ?=\'in_house\' THEN now() ELSE checked_in_at END,checked_out_at=CASE WHEN ?=\'checked_out\' THEN now() ELSE checked_out_at END WHERE id=?')->execute([$status,$status,$status,$status,$id]);if($booking['physical_room_id']){$roomStatus=$status==='in_house'?'occupied':($status==='checked_out'?'dirty':'clean');$pdo->prepare('UPDATE physical_rooms SET status=? WHERE id=?')->execute([$roomStatus,$booking['physical_room_id']]);if($status==='checked_out')$pdo->prepare("INSERT INTO housekeeping_tasks(property_id,physical_room_id,task_type,priority,status,notes) VALUES(?,?, 'checkout_cleaning','high','open','Check-out sonrası temizlik')")->execute([$booking['property_id'],$booking['physical_room_id']]);}$pdo->commit();$message='Rezervasyon durumu güncellendi.';}
if($action==='folio'){$folio=(int)$_POST['folio_id'];$amount=(float)$_POST['amount'];$type=$_POST['transaction_type']??'payment';if(!$folio||$amount<=0||!in_array($type,['room_charge','service_charge','payment','refund','adjustment','tax'],true))throw new RuntimeException('Folyo işlemi alanlarını kontrol edin.');$pdo->prepare('INSERT INTO folio_transactions(folio_id,transaction_type,department,description,amount,created_by) VALUES(?,?,?,?,?,?)')->execute([$folio,$type,trim((string)$_POST['department'])?:null,trim((string)$_POST['description'])?:$type,$type==='payment'||$type==='refund'?-$amount:$amount,$u['id']]);$message='Folyo işlemi kaydedildi.';}
}}
catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
$q=$pdo->prepare("SELECT id,name FROM properties WHERE supplier_id=? AND property_type='hotel' ORDER BY name");$q->execute([$u['supplier_id']]);$hotels=$q->fetchAll();$q=$pdo->prepare('SELECT pr.*,p.name property_name,rt.name room_type_name FROM physical_rooms pr JOIN properties p ON p.id=pr.property_id LEFT JOIN room_types rt ON rt.id=pr.room_type_id WHERE p.supplier_id=? ORDER BY p.name,pr.room_number');$q->execute([$u['supplier_id']]);$rooms=$q->fetchAll();$q=$pdo->prepare("SELECT b.*,p.name property_name,g.first_name,g.last_name,pr.room_number,f.id folio_id,COALESCE((SELECT SUM(amount) FROM folio_transactions ft WHERE ft.folio_id=f.id),0) balance FROM supplier_bookings b JOIN properties p ON p.id=b.property_id LEFT JOIN booking_guests bg ON bg.booking_id=b.id AND bg.is_primary=true LEFT JOIN guest_profiles g ON g.id=bg.guest_id LEFT JOIN booking_rooms br ON br.booking_id=b.id LEFT JOIN physical_rooms pr ON pr.id=br.physical_room_id LEFT JOIN booking_folios f ON f.booking_id=b.id AND f.folio_type='guest' WHERE b.supplier_id=? AND p.property_type='hotel' ORDER BY b.check_in DESC LIMIT 100");$q->execute([$u['supplier_id']]);$bookings=$q->fetchAll();supply_start('Otel operasyon merkezi',$active_module);?>
<section class="page-intro"><p>Ön büro, fiziksel oda, misafir, folyo ve check-in/check-out akışlarını tek merkezden yönetin.</p></section><?php if($message):?><p class="save-success">✓ <?=htmlspecialchars($message)?></p><?php endif;?><?php if($error):?><p class="login-error"><?=htmlspecialchars($error)?></p><?php endif;?><section class="next-module"><h2>Oda planı · fiziksel oda ekle</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="room"><div class="form-row"><label>Otel<select name="property_id"><?php foreach($hotels as $h):?><option value="<?=$h['id']?>"><?=htmlspecialchars($h['name'])?></option><?php endforeach;?></select></label><label>Oda tipi ID <input name="room_type_id" type="number" placeholder="Opsiyonel"></label><label>Oda no<input name="room_number" required placeholder="101"></label><label>Kat<input name="floor_label" placeholder="1. Kat"></label></div><button>Odayı ekle</button></form><?php foreach($rooms as $room):?><p><b><?=htmlspecialchars($room['property_name'])?></b> · <?=htmlspecialchars($room['room_number'])?> · <?=htmlspecialchars($room['room_type_name']??'Tip atanmamış')?> · <strong><?=htmlspecialchars($room['status'])?></strong></p><?php endforeach;?></section>
<section class="next-module"><h2>Manuel rezervasyon ve misafir kartı</h2><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="booking"><div class="form-row"><label>Otel<select name="property_id"><?php foreach($hotels as $h):?><option value="<?=$h['id']?>"><?=htmlspecialchars($h['name'])?></option><?php endforeach;?></select></label><label>Fiziksel oda<select name="physical_room_id"><?php foreach($rooms as $room):?><option value="<?=$room['id']?>"><?=htmlspecialchars($room['property_name'].' · '.$room['room_number'])?></option><?php endforeach;?></select></label><label>Giriş<input type="date" name="check_in" required></label><label>Çıkış<input type="date" name="check_out" required></label></div><div class="form-row"><label>Ad<input name="first_name" required></label><label>Soyad<input name="last_name" required></label><label>E-posta<input type="email" name="email"></label><label>Telefon<input name="phone"></label><label>Uyruk<input name="nationality" value="TR" maxlength="2"></label></div><div class="form-row"><label>Yetişkin<input type="number" name="adults" value="2" min="1"></label><label>Çocuk<input type="number" name="children" value="0" min="0"></label><label>Gecelik fiyat<input type="number" step="0.01" name="nightly_rate" value="0"></label><label>Toplam<input type="number" step="0.01" name="total_amount" value="0"></label><label>Para birimi<select name="currency"><option>EUR</option><option>TRY</option><option>USD</option><option>GBP</option></select></label></div><label>Not<textarea name="notes"></textarea></label><button>Rezervasyon oluştur</button></form></section>
<section class="next-module"><h2>Ön büro rezervasyonları</h2><?php foreach($bookings as $b):?><article><h3><?=htmlspecialchars($b['booking_reference'])?> · <?=htmlspecialchars($b['property_name'])?> / <?=htmlspecialchars($b['room_number']??'Oda atanmamış')?></h3><p><?=htmlspecialchars(trim(($b['first_name']??'').' '.($b['last_name']??'')))?> · <?=htmlspecialchars($b['check_in'])?> → <?=htmlspecialchars($b['check_out'])?> · <b><?=htmlspecialchars($b['booking_status'])?></b> · folyo bakiye <?=number_format((float)$b['balance'],2)?></p><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="status"><input type="hidden" name="booking_id" value="<?=$b['id']?>"><button name="status" value="in_house">Check-in</button><button name="status" value="checked_out">Check-out</button><button name="status" value="no_show">No-show</button><button name="status" value="cancelled">İptal</button></form><form method="post" class="supply-form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['supplier_csrf'])?>"><input type="hidden" name="action" value="folio"><input type="hidden" name="folio_id" value="<?=$b['folio_id']?>"><div class="form-row"><select name="transaction_type"><option value="payment">Tahsilat</option><option value="room_charge">Konaklama</option><option value="service_charge">Ek hizmet</option><option value="refund">İade</option><option value="adjustment">Düzeltme</option></select><input name="amount" type="number" min="0.01" step="0.01" placeholder="Tutar"><input name="department" placeholder="Departman"><input name="description" placeholder="Açıklama"></div><button>Folyoya işle</button></form></article><?php endforeach;?></section><?php supply_end();
